"""Held-out check for evals v2: a NEW fictional company and a NEW seed, 300 conversations generated by Opus 5.5
(same case-type ratios), judged with the v1 and v2 rubrics by the same 4 judges (Message Batches).

The rubric wording (criteria 1-6, the procedure manual, the v2 regional-norm notes) is NOT changed. Only the
company-specific facts block (社内ナレッジ: product names and their facts) is swapped for the new company, because
the judge has to know the new products' facts to judge "正確さ".

Output: outputs/<period>/evals_heldout/ja-cs-judge-evals-heldout/
  data/conversations.jsonl, results/judgments_<model>_{v1,v2}.csv, tables/heldout_v1_vs_v2.{md,json}
"""
from __future__ import annotations

import csv
import datetime as dt
import json
import random
from collections import Counter
from concurrent.futures import ThreadPoolExecutor

from ..core import ROOT, BudgetExceeded, Ctx, make_request, parse_json, run_batch, settings, write_jsonl
from .evals import (CASE_TYPES, GEN_SCHEMA, JUDGE_SCHEMA, NAME_TYPES, PER_GEN_REQUEST, REAL_NAME_PATTERN, SURNAMES,
                    render_conversation, valid_conversation, wilson)

NEW_COMPANY = "アオバ電機"
NEW_PRODUCTS = {
    "ハルカフォンS": ["充電が遅い", "画面が割れた", "アプリが起動しない", "動作が遅い", "通知が来ない", "電池の減りが早い"],
    "ハルカウォッチ3": ["心拍の表示がおかしい", "防水について", "画面がつかない", "接続できない", "文字盤の変え方", "バンド交換"],
    "アオバノート": ["同期されない", "起動しない", "メモが消えた気がする", "表示されない", "共有の設定"],
    "アオバドライブ": ["解約と返金", "容量不足", "接続できない", "登録メールの変更", "請求内容の確認", "アップロードが終わらない"],
}
NEW_GEN_SETTING = """# 架空の設定
会社：アオバ電機（サポート窓口は「アオバ電機サポート」）
製品：ハルカフォンS（スマホ、発売済み）、ハルカウォッチ3（腕時計型、発売済み）、アオバノート（メモアプリ）、アオバドライブ（保存サービス、年額の有料プランあり）
社内手順書：起動しない→アプリのバージョン確認→だめなら二次窓口へ転送／接続できない→アプリから再接続→だめなら二次窓口へ転送／動作が遅い→二次窓口へ転送
社内ナレッジ：ハルカウォッチ3は30メートル防水（手洗い・雨は可、水泳・お湯・サウナは不可）／アオバドライブの年額プランは途中解約しても残り期間分を返金しない／修理は通常7営業日、期日は確約しない
"""
OLD_KNOWLEDGE_JUDGE = """【社内ナレッジ（正しい情報）】
- ソラバンド2：50メートル防水（手洗い・水泳は可、お湯・サウナは不可）
- ミドリクラウド：月の途中で解約しても、その月の料金は返金しない
- 修理：通常5営業日かかる。期日の確約はしない"""
NEW_KNOWLEDGE_JUDGE = """【社内ナレッジ（正しい情報）】
- ハルカウォッチ3：30メートル防水（手洗い・雨は可、水泳・お湯・サウナは不可）
- アオバドライブ：年額プランを途中で解約しても、残り期間分の料金は返金しない
- 修理：通常7営業日かかる。期日の確約はしない"""
SEED = "heldout-aoba-2026-11-27"
SCALE = 0.3                                       # 1000 -> 300, same ratios
VIOLATIONS = [ct for ct, v in CASE_TYPES.items() if v[1] == 1]
FOCUS = ["名字様", "一般手順", "文字起こし崩れ"]


def make_specs() -> list[dict]:
    rng = random.Random(SEED)
    specs = []
    for ct, (n, *_rest) in CASE_TYPES.items():
        for _ in range(round(n * SCALE)):
            prod = rng.choice(list(NEW_PRODUCTS))
            specs.append({"case_type": ct, "product": prod, "hint": rng.choice(NEW_PRODUCTS[prod]),
                          "surname": rng.choice(SURNAMES)})
    rng.shuffle(specs)
    for i, s in enumerate(specs):
        s["spec_id"] = f"H{i + 1:04d}"
    return specs


def gen_prompt() -> str:
    """The v1 generator prompt with only the company block swapped (case-type instructions unchanged)."""
    src = (ROOT / "prompts" / "evals_generate_system.md").read_text(encoding="utf-8")
    start, end = src.index("# 架空の設定"), src.index("# 種類（case_type）")
    out = src[:start] + NEW_GEN_SETTING + "\n" + src[end:]
    assert "ミドリ" not in out and "ソラ" not in out, "old company name left in the generator prompt"
    return out


def judge_prompt(version: str) -> str:
    """v1/v2 judge prompt with only the company facts block swapped. Criteria and notes are byte-identical."""
    name = "evals_judge_system.md" if version == "v1" else "evals_judge_system_v2.md"
    src = (ROOT / "prompts" / name).read_text(encoding="utf-8")
    assert OLD_KNOWLEDGE_JUDGE in src
    out = src.replace(OLD_KNOWLEDGE_JUDGE, NEW_KNOWLEDGE_JUDGE)
    assert "ミドリ" not in out and "ソラ" not in out
    return out


def check_deadline(deadline: str) -> None:
    dl = dt.datetime.fromisoformat(deadline)
    now = dt.datetime.now(dl.tzinfo)
    worst = now + dt.timedelta(hours=settings()["batch_timeout_hours"])
    if worst > dl:
        raise BudgetExceeded(f"worst-case finish {worst:%F %T} is after the deadline {dl:%F %T}: not submitting")


def _judge(ctx, jc, model, version, dataset, system, log) -> dict:
    effort = None if model in jc.get("default_effort_models", []) else jc.get("effort")
    est = jc.get("est_output_tokens_by_model", {}).get(model, jc["est_output_tokens"])
    reqs = [make_request(d["id"], model=model, system=system, user=render_conversation(d["conversation"]),
                         max_tokens=jc["max_tokens"], schema=JUDGE_SCHEMA, effort=effort) for d in dataset]
    res = run_batch(ctx, f"judge-{version}-{model.replace('claude-', '')}", reqs, est, log)
    return {cid: j for cid, rec in res.items() if (j := parse_json(rec)) is not None}


def run(ctx: Ctx, job: dict, log=print) -> dict:
    if job.get("deadline") and "generate" not in ctx.state.get("batches", {}):
        check_deadline(job["deadline"])
    gc, jc = job["stages"]["generate"], job["stages"]["judge"]
    specs = make_specs()
    if ctx.limit:
        specs = specs[: ctx.limit]
    sys_gen = gen_prompt()
    gen_reqs = []
    for gi in range(0, len(specs), PER_GEN_REQUEST):
        chunk = specs[gi:gi + PER_GEN_REQUEST]
        user = "次の spec ごとに会話を1つずつ書いてください。\n" + json.dumps(
            [{k: s[k] for k in ("spec_id", "case_type", "product", "hint", "surname")
              if k != "surname" or s["case_type"] in NAME_TYPES} for s in chunk], ensure_ascii=False, indent=1)
        gen_reqs.append(make_request(f"gen-{gi // PER_GEN_REQUEST:03d}", model=gc["model"], system=sys_gen, user=user,
                                     max_tokens=gc["max_tokens"], schema=GEN_SCHEMA, effort=gc.get("effort")))
    raw = run_batch(ctx, "generate", gen_reqs, gc["est_output_tokens"], log)
    convs = {it["spec_id"]: it["conversation"] for rec in raw.values() for it in (parse_json(rec) or {}).get("items", [])}
    dataset, dropped = [], Counter()
    for s in specs:
        text = convs.get(s["spec_id"])
        if text is None:
            dropped["missing"] += 1
        elif REAL_NAME_PATTERN.search(text) or "ミドリ" in text or "ソラ" in text:
            dropped["real_or_old_name"] += 1
        elif not valid_conversation(text):
            dropped["format"] += 1
        else:
            gold = CASE_TYPES[s["case_type"]][1]
            dataset.append({"id": s["spec_id"], "case_type": s["case_type"], "gold_deduct": gold,
                            "product": s["product"], "conversation": text.strip()})
    repo = ctx.out_dir / "ja-cs-judge-evals-heldout"
    write_jsonl(repo / "data" / "conversations.jsonl", dataset)
    log(f"[evals_heldout] dataset {len(dataset)}/{len(specs)} kept; dropped={dict(dropped)}")

    prompts = {v: judge_prompt(v) for v in ("v1", "v2")}
    res: dict[tuple[str, str], dict] = {}
    failed = []

    def wave(models):
        pairs = [(m, v) for m in models for v in ("v1", "v2")]
        with ThreadPoolExecutor(max_workers=len(pairs)) as ex:
            futs = {p: ex.submit(_judge, ctx, jc, p[0], p[1], dataset, prompts[p[1]], log) for p in pairs}
        for p, f in futs.items():
            try:
                res[p] = f.result()
            except BudgetExceeded as e:
                failed.append(f"{p[0]}/{p[1]}")
                log(f"[evals_heldout] {p} SKIPPED (budget): {e}")
            except Exception as e:  # noqa: BLE001
                failed.append(f"{p[0]}/{p[1]}")
                log(f"[evals_heldout] {p} FAILED: {e!r}")

    models = jc["models"]
    expensive = [m for m in models if m in jc.get("last_wave_models", [])]
    wave([m for m in models if m not in expensive])     # cheap judges first
    if expensive:
        wave(expensive)                                  # then the expensive one, checked against what is left

    gold = {d["id"]: d for d in dataset}
    (repo / "results").mkdir(parents=True, exist_ok=True)
    for (m, v), j in res.items():
        with open(repo / "results" / f"judgments_{m}_{v}.csv", "w", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            w.writerow(["id", "case_type", "gold_deduct", "deduct", "criterion", "reason"])
            for cid, x in sorted(j.items()):
                w.writerow([cid, gold[cid]["case_type"], gold[cid]["gold_deduct"], x["deduct"], x["criterion"], x["reason"]])
    table = compare(dataset, res, models)
    write_tables(repo, dataset, table, models, dropped)
    return {"outputs": [str(repo)], "failed": failed,
            "counts": {"conversations": len(dataset), **{f"judgments_{m}_{v}": len(j) for (m, v), j in res.items()}}}


def compare(dataset, res, models) -> dict:
    """Per case type: deduction rate over conversations whose gold is "no deduction" (label revisions respected);
    violations: detection over every conversation whose gold is "deduct"."""
    gold = {d["id"]: d for d in dataset}
    out: dict = {"by_type": {}, "violations": {}}
    for m in models:
        if (m, "v1") not in res or (m, "v2") not in res:
            continue
        v1, v2 = res[(m, "v1")], res[(m, "v2")]
        for ct in CASE_TYPES:
            ids = [c for c in gold if gold[c]["case_type"] == ct and gold[c]["gold_deduct"] == 0 and c in v1 and c in v2]
            k1, k2, n = sum(v1[c]["deduct"] for c in ids), sum(v2[c]["deduct"] for c in ids), len(ids)
            out["by_type"].setdefault(ct, {})[m] = dict(n=n, k1=k1, k2=k2, v1_ci=list(wilson(k1, n)), v2_ci=list(wilson(k2, n)))
        ids = [c for c in gold if gold[c]["gold_deduct"] == 1 and c in v1 and c in v2]
        k1, k2 = sum(v1[c]["deduct"] for c in ids), sum(v2[c]["deduct"] for c in ids)
        out["violations"][m] = dict(n=len(ids), k1=k1, k2=k2, v1_ci=list(wilson(k1, len(ids))), v2_ci=list(wilson(k2, len(ids))))
    return out


LABEL_REVISIONS: dict = {}  # superseded by apijobs/jobs/label_audit.py (2026-11-27 rule)


def relabel_and_rebuild(repo, models) -> dict:
    """Apply LABEL_REVISIONS to data and result CSVs, then rebuild the tables from the CSVs (no API calls)."""
    path = repo / "data" / "conversations.jsonl"
    dataset = [json.loads(l) for l in path.read_text(encoding="utf-8").splitlines() if l]
    for d in dataset:
        if d["id"] in LABEL_REVISIONS:
            g, note = LABEL_REVISIONS[d["id"]]
            d.setdefault("gold_deduct_original", d["gold_deduct"])
            d["gold_deduct"], d["label_note"] = g, note
            if g == 1:
                d["gold_criterion"] = 5
    write_jsonl(path, dataset)
    gold = {d["id"]: d for d in dataset}
    res = {}
    for m in models:
        for v in ("v1", "v2"):
            f = repo / "results" / f"judgments_{m}_{v}.csv"
            rows = list(csv.DictReader(open(f, encoding="utf-8")))
            for r in rows:
                r["gold_deduct"] = gold[r["id"]]["gold_deduct"]
            with open(f, "w", newline="", encoding="utf-8") as fh:
                w = csv.DictWriter(fh, fieldnames=["id", "case_type", "gold_deduct", "deduct", "criterion", "reason"])
                w.writeheader()
                w.writerows(rows)
            res[(m, v)] = {r["id"]: {"deduct": int(r["deduct"]), "criterion": int(r["criterion"]), "reason": r["reason"]} for r in rows}
    table = compare(dataset, res, models)
    write_tables(repo, dataset, table, models, {})
    return table


def _cell(k, n, ci):
    return f"{k}/{n} = {k / max(1, n):.1%} [{ci[0]:.1%}–{ci[1]:.1%}]"


def write_tables(repo, dataset, t, models, dropped) -> None:
    L = ["# held-out：新しい架空企業（アオバ電機）・新しいシードの300件（生成 Opus 5.5）", "",
         f"会話 {len(dataset)} 件（除外 {dict(dropped)}）。ルーブリックの文言（基準1〜6・手順書・v2の注記）は変更せず、"
         "社内ナレッジの製品名と事実だけを新しい会社のものに差し替えた。", "",
         "率は 減点した割合 [Wilson 95%CI]。正解ラベルは本人確認の規則（氏名＋登録情報1項目を顧客が実際に答え、担当が照合した場合のみ可）で監査済み（2026-11-27、label_note 参照）。"
         "誤減点率は各種類のうち正解が減点なしの会話だけ、検出率は正解が減点の会話すべてで計算。", "",
         "## 誤減点率（正解は減点なし）", "", "| 種類 | model | v1 | v2 | 差 (pp) |", "|---|---|---|---|---|"]
    for ct in [*FOCUS, "発売済み機能", "問題なし"]:
        for m in models:
            d = t["by_type"].get(ct, {}).get(m)
            if d:
                L.append(f"| {ct} | {m} | {_cell(d['k1'], d['n'], d['v1_ci'])} | {_cell(d['k2'], d['n'], d['v2_ci'])} | "
                         f"{(d['k2'] - d['k1']) / max(1, d['n']) * 100:+.1f} |")
    L += ["", "## 違反の検出率（正解が減点の会話すべて）", "", "| model | v1 | v2 |", "|---|---|---|"]
    for m in models:
        d = t["violations"].get(m)
        if d:
            L.append(f"| {m} | {_cell(d['k1'], d['n'], d['v1_ci'])} | {_cell(d['k2'], d['n'], d['v2_ci'])} |")
    (repo / "tables").mkdir(parents=True, exist_ok=True)
    (repo / "tables" / "heldout_v1_vs_v2.md").write_text("\n".join(L) + "\n", encoding="utf-8")
    (repo / "tables" / "heldout_v1_vs_v2.json").write_text(json.dumps(t, ensure_ascii=False, indent=2))
